-- Disposable database only. Vault shim verifies access/transactions, not encryption.
begin;
create schema automation_test;
create function automation_test.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'ok - automation: %',label;end$$;
create function automation_test.fails(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then raise notice 'ok - automation: % (refused)',label;return;end;raise exception 'FAIL: % was permitted',label;end$$;
grant usage on schema automation_test to anon,authenticated,service_role;
grant execute on all functions in schema automation_test to anon,authenticated,service_role;
insert into auth.users(id,email,email_confirmed_at) values('cb000000-0000-4000-8000-000000000001','verified@example.com',now()),('cb000000-0000-4000-8000-000000000002','unverified@example.com',null);
insert into public.organizations(id,name,slug) values('cb000000-0000-4000-8000-000000000011','Automation A','automation-a'),('cb000000-0000-4000-8000-000000000012','Automation B','automation-b');
insert into public.organization_members(organization_id,user_id,role,status) values('cb000000-0000-4000-8000-000000000011','cb000000-0000-4000-8000-000000000001','owner','active'),('cb000000-0000-4000-8000-000000000012','cb000000-0000-4000-8000-000000000002','owner','active');
insert into public.websites(id,organization_id,name,status,live_url) values('cb000000-0000-4000-8000-000000000021','cb000000-0000-4000-8000-000000000011','Automation A','building','https://client.example.com'),('cb000000-0000-4000-8000-000000000022','cb000000-0000-4000-8000-000000000012','Automation B','live','https://b.example.com');
select automation_test.ok((select status='needs_recipient' from public.website_contact_automation where website_id='cb000000-0000-4000-8000-000000000022'),'unverified owner never becomes notification destination');
insert into public.domains(id,organization_id,website_id,hostname,kind,status,dns_ok,ssl_ok) values('cb000000-0000-4000-8000-000000000041','cb000000-0000-4000-8000-000000000011','cb000000-0000-4000-8000-000000000021','client.example.com','subdomain','connected',true,true);
select automation_test.ok((select count(*)=0 from public.provisioning_jobs where kind='website.contact.configure'),'building website cannot start provider configuration');
update public.websites set status='live' where id='cb000000-0000-4000-8000-000000000021';
select automation_test.ok((select notification_email='verified@example.com' and not enabled from public.website_contact_settings where website_id='cb000000-0000-4000-8000-000000000021'),'verified owner default starts disabled');
select automation_test.ok((select count(*)=1 from public.provisioning_jobs where kind='website.contact.configure'),'launch transition queues a durable job');
select set_config('automation_test.generation',(select generation::text from public.website_contact_automation where website_id='cb000000-0000-4000-8000-000000000021'),true);
select automation_test.ok(vigil.contact_verified_origins('cb000000-0000-4000-8000-000000000021')=array['https://client.example.com'],'only verified origins derived');
select automation_test.ok(vigil.contact_verified_origins('cb000000-0000-4000-8000-000000000022')='{}'::text[],'arbitrary live_url is not hostname authority');
select set_config('request.jwt.claim.role','service_role',true);
set local role service_role;
select automation_test.fails('select * from vigil.contact_secret_refs','service cannot read private Vault reference table directly');
select automation_test.fails('select * from vault.decrypted_secrets','service cannot read Vault directly');
select automation_test.ok((public.claim_contact_setup('cb000000-0000-4000-8000-000000000021',current_setting('automation_test.generation')::int,'cb000000-0000-4000-8000-000000000031')->>'claimed')::boolean,'worker acquires lease');
select automation_test.ok(public.claim_contact_setup('cb000000-0000-4000-8000-000000000021',current_setting('automation_test.generation')::int,'cb000000-0000-4000-8000-000000000032')->>'status'='busy','second worker cannot acquire live lease');
select public.contact_setup_failed('cb000000-0000-4000-8000-000000000021',current_setting('automation_test.generation')::int,'cb000000-0000-4000-8000-000000000032','failed','other worker');
select public.mark_contact_widget_creation('cb000000-0000-4000-8000-000000000021','cb000000-0000-4000-8000-000000000031');
select automation_test.fails($q$select public.mark_contact_widget_creation('cb000000-0000-4000-8000-000000000021','cb000000-0000-4000-8000-000000000031')$q$,'creation cannot start twice');
select automation_test.ok(public.finish_contact_setup('cb000000-0000-4000-8000-000000000021',current_setting('automation_test.generation')::int,'cb000000-0000-4000-8000-000000000031','fixture-sitekey','fixture-secret-not-real',repeat('a',32),array['https://client.example.com']),'current verified revision activates');
select automation_test.ok(public.contact_widget_credentials('cb000000-0000-4000-8000-000000000021')->>'secret'='fixture-secret-not-real','service RPC obtains website credential');
reset role;
select automation_test.ok((select not (metadata ? 'secret') from public.provider_links where external_id='fixture-sitekey'),'provider metadata contains no secret');
select automation_test.ok((select status='ready' from public.website_contact_automation where website_id='cb000000-0000-4000-8000-000000000021'),'state is ready');
update public.domains set hostname='changed.example.com' where id='cb000000-0000-4000-8000-000000000041';
select automation_test.ok((select not enabled from public.website_contact_settings where website_id='cb000000-0000-4000-8000-000000000021'),'domain change immediately disables capture');
select automation_test.ok(vigil.contact_verified_origins('cb000000-0000-4000-8000-000000000021')=array['https://changed.example.com'],'removed domain cannot linger via old live_url');
set local role service_role;
select automation_test.ok(public.contact_widget_credentials('cb000000-0000-4000-8000-000000000021') is null,'old-domain credentials cannot be served');
select automation_test.ok(public.claim_contact_setup('cb000000-0000-4000-8000-000000000021',current_setting('automation_test.generation')::int,'cb000000-0000-4000-8000-000000000031')->>'status'='superseded','old job is superseded');
reset role;
select set_config('automation_test.generation',(select generation::text from public.website_contact_automation where website_id='cb000000-0000-4000-8000-000000000021'),true);
set local role service_role;
select public.claim_contact_setup('cb000000-0000-4000-8000-000000000021',current_setting('automation_test.generation')::int,'cb000000-0000-4000-8000-000000000031');
reset role;
update public.domains set ssl_ok=false where id='cb000000-0000-4000-8000-000000000041';
set local role service_role;
select automation_test.ok(not public.finish_contact_setup('cb000000-0000-4000-8000-000000000021',current_setting('automation_test.generation')::int,'cb000000-0000-4000-8000-000000000031','fixture-sitekey','fixture-updated-secret',repeat('a',32),array['https://changed.example.com']),'in-flight setup cannot activate superseded origins');
reset role;
select automation_test.ok((select count(*)=1 from vault.secrets),'domain update reuses stored Vault secret');
select automation_test.ok((select not enabled from public.website_contact_settings where website_id='cb000000-0000-4000-8000-000000000021'),'stale finish remains disabled');

insert into public.website_contact_settings(website_id,organization_id,notification_email) values('cb000000-0000-4000-8000-000000000022','cb000000-0000-4000-8000-000000000012','approved@example.com');
insert into public.domains(organization_id,website_id,hostname,kind,status,dns_ok,ssl_ok) values('cb000000-0000-4000-8000-000000000012','cb000000-0000-4000-8000-000000000022','b.example.com','subdomain','connected',true,true);
select set_config('automation_test.b_generation',(select generation::text from public.website_contact_automation where website_id='cb000000-0000-4000-8000-000000000022'),true);
set local role service_role;
select automation_test.fails($q$select public.finish_contact_setup('cb000000-0000-4000-8000-000000000022',2,null,'second-fixture','fixture-secret-should-not-save',repeat('a',32),array['https://b.example.com'])$q$,'null lease cannot persist credentials');
select public.claim_contact_setup('cb000000-0000-4000-8000-000000000022',current_setting('automation_test.b_generation')::int,'cb000000-0000-4000-8000-000000000032');
select automation_test.fails($q$select public.finish_contact_setup('cb000000-0000-4000-8000-000000000022',current_setting('automation_test.b_generation')::int,'cb000000-0000-4000-8000-000000000032','fixture-sitekey','fixture-secret-should-not-save',repeat('a',32),array['https://b.example.com'])$q$,'widget association cannot cross websites');
select public.mark_contact_widget_creation('cb000000-0000-4000-8000-000000000022','cb000000-0000-4000-8000-000000000032');
select public.contact_setup_failed('cb000000-0000-4000-8000-000000000022',current_setting('automation_test.b_generation')::int,'cb000000-0000-4000-8000-000000000032','queued','Safe fixture timeout');
select automation_test.ok((public.claim_contact_setup('cb000000-0000-4000-8000-000000000022',current_setting('automation_test.b_generation')::int,'cb000000-0000-4000-8000-000000000033')->>'creation_started')::boolean,'uncertain creation marker survives retries');
reset role;
select automation_test.ok((select count(*)=1 from vault.secrets),'failed association rolls back Vault write atomically');
select automation_test.ok((select vault_secret_id is null from vigil.contact_secret_refs where website_id='cb000000-0000-4000-8000-000000000022'),'failed association leaves no usable credential reference');

select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','cb000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select automation_test.ok((select count(*)=1 from public.website_contact_automation),'tenant reads only its own automation state');
select automation_test.fails('select * from vault.decrypted_secrets','tenant cannot access Vault');
select automation_test.fails('select * from vigil.contact_secret_refs','tenant cannot access credential references');
select automation_test.fails($q$select public.contact_widget_credentials('cb000000-0000-4000-8000-000000000021')$q$,'tenant cannot decrypt contact credential');
select automation_test.fails($q$select public.set_website_contact_automation('cb000000-0000-4000-8000-000000000021',true)$q$,'owner cannot launch or retry provider work');
select automation_test.fails('select public.reconcile_contact_setup()','tenant cannot reconcile provider work');
reset role;
insert into public.staff_members(user_id,role) values('cb000000-0000-4000-8000-000000000001','admin');
set local role authenticated;
select public.set_website_contact_automation('cb000000-0000-4000-8000-000000000021',false);
select public.configure_website_contact('cb000000-0000-4000-8000-000000000021','client-choice@example.com',null);
reset role;
update public.domains set ssl_ok=true where id='cb000000-0000-4000-8000-000000000041';
select automation_test.ok((select not automatic and status='paused' from public.website_contact_automation where website_id='cb000000-0000-4000-8000-000000000021'),'domain lifecycle preserves staff pause');
select set_config('request.jwt.claim.role','anon',true);
set local role anon;
select automation_test.fails('select * from public.website_contact_automation','anonymous cannot read setup');
select automation_test.fails($q$select public.contact_widget_credentials('cb000000-0000-4000-8000-000000000021')$q$,'anonymous cannot decrypt credential');
reset role;
rollback;
